/**
 * Code generated from plugin.json so parameter indices, ranges and defaults
 * are declared once:
 *
 *  - generated/audiospan_params.h   C++: enum of indices + `plugin::kParameters` table
 *  - generated/audiospan_params.rs  Rust: index constants + `PARAMETERS` table
 *  - dist/plugin.d.ts               TypeScript: typed ids for the host application
 *
 * `audiospan build` and `audiospan create` write these; `audiospan generate`
 * refreshes them without building.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import type { NormalizedOutput, NormalizedParameter, NormalizedPluginManifest } from "@audiospan/manifest";
import { CliError } from "./errors.js";

export interface GeneratedBindings {
  /** C++ header for `#include "audiospan_params.h"`. */
  header: string;
  /** Rust module for `#[path = "../generated/audiospan_params.rs"] mod params;`. */
  rustModule: string;
  /** TypeScript declarations for the host application. */
  types: string;
}

const BANNER = (manifest: NormalizedPluginManifest) => `Generated by \`audiospan build\` from plugin.json (${manifest.id} ${manifest.version}). Do not edit; edit plugin.json.`;

/** Split a manifest id into words: `dry-wet`, `dry_wet` and `dryWet` all give ["dry", "Wet"] / ["dry", "wet"]. */
function words(id: string): string[] {
  return id.split(/[-_]+|(?<=[a-z0-9])(?=[A-Z])/).filter((w) => w.length > 0);
}

/** `cutoff` → `kCutoff`, `dry-wet` → `kDryWet`. */
export function cppConstant(id: string, prefix = "k"): string {
  return prefix + words(id).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
}

/** `cutoff` → `CUTOFF`, `dryWet` → `DRY_WET`. */
export function rustConstant(id: string, prefix = ""): string {
  return prefix + words(id).map((w) => w.toUpperCase()).join("_");
}

/** `com.example.my_filter` → `MyFilter`: the prefix of the generated TypeScript type names. */
export function typePrefix(manifest: NormalizedPluginManifest): string {
  const label = manifest.id.split(".").pop() ?? manifest.id;
  const name = words(label).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
  return /^[0-9]/.test(name) ? `Plugin${name}` : name || "Plugin";
}

function assertUnique(kind: string, items: readonly { id: string }[], toName: (id: string) => string): void {
  const seen = new Map<string, string>();
  for (const item of items) {
    const name = toName(item.id);
    const other = seen.get(name);
    if (other !== undefined) {
      throw new CliError(`${kind} ids ${JSON.stringify(other)} and ${JSON.stringify(item.id)} both generate the identifier ${name}`, 3, "rename one of them in plugin.json");
    }
    seen.set(name, item.id);
  }
}

/** A JSON number as a C++/Rust floating-point literal. */
function literal(n: number): string {
  if (Number.isInteger(n)) return `${n}.0`;
  return String(n);
}

const KIND_CPP: Record<NormalizedParameter["type"], string> = { float: "Float", integer: "Integer", boolean: "Boolean", enum: "Enum" };

function describe(p: NormalizedParameter): string {
  const range = p.type === "enum" ? `${p.options.length} options` : `${p.min}..${p.max}`;
  return `"${p.id}" (${p.type}, ${range}, default ${p.default})`;
}

export function generateCppHeader(manifest: NormalizedPluginManifest): string {
  assertUnique("parameter", manifest.parameters, (id) => cppConstant(id));
  assertUnique("output", manifest.outputs, (id) => cppConstant(id, "kOut"));
  const lines: string[] = [];
  lines.push(`// ${BANNER(manifest)}`, "#pragma once", "", '#include "audiospan/effect.hpp"', "", "namespace plugin {", "");
  lines.push(`constexpr const char* kId = ${JSON.stringify(manifest.id)};`, `constexpr const char* kVersion = ${JSON.stringify(manifest.version)};`, "");
  lines.push("enum Param : uint32_t {");
  manifest.parameters.forEach((p, i) => lines.push(`  ${cppConstant(p.id)} = ${i},  // ${describe(p)}`));
  lines.push(`  kParamCount = ${manifest.parameters.length}`, "};", "");
  if (manifest.parameters.length > 0) {
    lines.push("inline constexpr audiospan::ParameterSpec kParameters[kParamCount] = {");
    for (const p of manifest.parameters) {
      lines.push(`  {${JSON.stringify(p.id)}, audiospan::ParameterKind::${KIND_CPP[p.type]}, ${literal(p.min)}, ${literal(p.max)}, ${literal(p.default)}, ${literal(p.step ?? 0)}},`);
    }
    lines.push("};", "", "using Parameters = audiospan::Parameters<kParamCount>;", "");
  }
  lines.push("enum Output : uint32_t {");
  manifest.outputs.forEach((o: NormalizedOutput, i) => lines.push(`  ${cppConstant(o.id, "kOut")} = ${i},  // "${o.id}" (${o.min}..${o.max})`));
  lines.push(`  kOutputCount = ${manifest.outputs.length}`, "};", "", "}  // namespace plugin", "");
  return lines.join("\n");
}

export function generateRustModule(manifest: NormalizedPluginManifest): string {
  assertUnique("parameter", manifest.parameters, (id) => rustConstant(id));
  assertUnique("output", manifest.outputs, (id) => rustConstant(id, "OUT_"));
  const lines: string[] = [];
  lines.push(`// ${BANNER(manifest)}`, "#![allow(dead_code)]", "", "use crate::abi::{ParameterKind, ParameterSpec};", "");
  lines.push(`pub const ID: &str = ${JSON.stringify(manifest.id)};`, `pub const VERSION: &str = ${JSON.stringify(manifest.version)};`, "");
  manifest.parameters.forEach((p, i) => lines.push(`pub const ${rustConstant(p.id)}: u32 = ${i}; // ${describe(p)}`));
  lines.push(`pub const PARAMETER_COUNT: u32 = ${manifest.parameters.length};`, "");
  lines.push(`pub static PARAMETERS: [ParameterSpec; ${manifest.parameters.length}] = [`);
  for (const p of manifest.parameters) {
    lines.push(`    ParameterSpec { id: ${JSON.stringify(p.id)}, kind: ParameterKind::${KIND_CPP[p.type]}, min: ${literal(p.min)}, max: ${literal(p.max)}, default: ${literal(p.default)}, step: ${literal(p.step ?? 0)} },`);
  }
  lines.push("];", "");
  manifest.outputs.forEach((o, i) => lines.push(`pub const ${rustConstant(o.id, "OUT_")}: u32 = ${i}; // "${o.id}" (${o.min}..${o.max})`));
  lines.push(`pub const OUTPUT_COUNT: u32 = ${manifest.outputs.length};`, "");
  return lines.join("\n");
}

function union(ids: readonly string[]): string {
  return ids.length === 0 ? "never" : ids.map((id) => JSON.stringify(id)).join(" | ");
}

export function generateTypes(manifest: NormalizedPluginManifest): string {
  const prefix = typePrefix(manifest);
  return [
    `// ${BANNER(manifest)}`,
    'import type { TypedPluginInstance } from "@audiospan/sdk";',
    "",
    `export type ${prefix}PluginId = ${JSON.stringify(manifest.id)};`,
    `export type ${prefix}ParameterId = ${union(manifest.parameters.map((p) => p.id))};`,
    `export type ${prefix}OutputId = ${union(manifest.outputs.map((o) => o.id))};`,
    `export type ${prefix}PresetId = ${union(manifest.presets.map((p) => p.id))};`,
    "",
    "/** A PluginInstance whose parameter, output and preset ids are checked at compile time:",
    ` *  \`const plugin = await host.addPlugin<${prefix}Plugin>(url);\` */`,
    `export type ${prefix}Plugin = TypedPluginInstance<${prefix}ParameterId, ${prefix}OutputId, ${prefix}PresetId>;`,
    "",
  ].join("\n");
}

export function generateBindings(manifest: NormalizedPluginManifest): GeneratedBindings {
  return { header: generateCppHeader(manifest), rustModule: generateRustModule(manifest), types: generateTypes(manifest) };
}

export const GENERATED_DIR = "generated";

/** Write the language bindings for a project into `<root>/generated/`. Returns the paths written. */
export async function writeBindings(root: string, language: "cpp" | "rust", manifest: NormalizedPluginManifest): Promise<string[]> {
  const dir = resolve(root, GENERATED_DIR);
  await mkdir(dir, { recursive: true });
  const path = resolve(dir, language === "cpp" ? "audiospan_params.h" : "audiospan_params.rs");
  await writeFile(path, language === "cpp" ? generateCppHeader(manifest) : generateRustModule(manifest));
  return [path];
}

/** Write the TypeScript declarations to `path`, creating directories as needed. */
export async function writeTypes(path: string, manifest: NormalizedPluginManifest): Promise<string> {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, generateTypes(manifest));
  return path;
}
